# Embedded transparent Saleae logo asset.
# The file is auto-created next to this script when missing.
SALEAE_LOGO_PNG_BASE64 = """"""

# Embedded application/window icon asset.
# Used by get_app_icon(); PyInstaller also embeds app_icon.ico into the final EXE.
APP_ICON_ICO_BASE64 = """"""


def get_embedded_logo_pixmap():
    """Return the embedded Saleae header logo as QPixmap.

    The logo is embedded directly in this Python file, so the program does not
    require a separate PNG file when distributed as a single script or EXE.
    """
    pixmap = QPixmap()
    pixmap.loadFromData(base64.b64decode(SALEAE_LOGO_PNG_BASE64), "PNG")
    return pixmap


def resource_path(filename):
    """Return a path to bundled runtime resources.

    In normal Python execution, resources are loaded from the script folder.
    In a PyInstaller one-file EXE, resources are loaded from sys._MEIPASS.
    """
    base = getattr(sys, "_MEIPASS", None)
    if base:
        return Path(base) / filename
    return Path(__file__).resolve().with_name(filename)


def get_app_icon():
    """Return the embedded application/window icon.

    The icon bytes are embedded directly in this Python file so the runtime
    program and one-file EXE do not depend on an external app_icon.ico file.
    """
    icon = QIcon()
    try:
        pixmap = QPixmap()
        if pixmap.loadFromData(base64.b64decode(APP_ICON_ICO_BASE64), "ICO"):
            icon.addPixmap(pixmap)
            return icon
    except Exception:
        pass

    # Fallback for development builds only. The final EXE should not rely on this.
    icon_path = resource_path("app_icon.ico")
    if icon_path.exists():
        return QIcon(str(icon_path))
    return icon

# ============================================================
# Analysis Defaults
# ============================================================
# 차동쌍 +와 -가 같은 상태로 보이는 시간 허용값.
# 5 MS/s에서는 1 sample = 0.2 us입니다.
# 정상 CSV에서는 CLK pair의 equal 상태가 대부분 0.2 us였으므로,
# 500 kbit/s 수신 관점에서 1 us 초과 equal 상태를 NG로 봅니다.
DIFF_EQUAL_MAX_SEC = 1.0e-6

# Ch0 글리치 제거: 기대 half-period의 이 비율보다 짧은 edge 간격은 glitch로 무시.
REF_GLITCH_HALF_PERIOD_RATIO = 0.25

# Ch0 edge glitch 비율이 너무 높으면 NG.
# 첨부 정상 CSV 기준 약 15%의 매우 짧은 edge가 보였으므로, 기본 hard fail은 30%로 둡니다.
REF_MAX_GLITCH_EDGE_RATIO = 0.30

# SSI CLOCK active half-period 비교 허용값.
# 5 MS/s에서 500 kHz clock의 half-period 1 us는 0.2 us 양자화 오차가 커서 ±25%로 시작.
SSI_CLK_HALF_PERIOD_TOL_PERCENT = 25.0

# SSI CLOCK active edge count 비교 허용값.
SSI_CLK_EDGE_COUNT_TOL_PERCENT = 20.0

# SSI CLOCK frame/clock-break gap 비교 허용값.
SSI_CLK_LONG_GAP_TOL_PERCENT = 50.0

# DATA는 실제 값 변화에 따라 edge 수가 변동될 수 있어 비교를 넓게 줍니다.
# 다만 static 조건에서 baseline 대비 너무 적어지면 DATA가 stuck된 것으로 봅니다.
SSI_DATA_EDGE_COUNT_DROP_LIMIT = 0.50   # baseline 대비 50% 미만이면 NG
SSI_DATA_EDGE_COUNT_RISE_LIMIT = 2.00   # baseline 대비 200% 초과면 NG

# DATA가 일정 시간 이상 전혀 변하지 않으면 stuck으로 봅니다.
# baseline max stable time의 3배 또는 5 ms 중 더 큰 값까지 허용.
SSI_DATA_STUCK_MULTIPLIER = 3.0
SSI_DATA_STUCK_MIN_LIMIT_SEC = 0.005

# Single-sample SSI waveform irregularities are treated as transient observations.
# They are promoted to FAIL only when the same class of abnormality repeats.
# This prevents a single missing clock burst during a 10 s sample from failing the full test.
SOFT_FAIL_CONFIRM_COUNT = 3

# Export/parse/runtime errors are not waveform transients and remain immediate FAIL.
IMMEDIATE_FAIL_EVENT_TYPES = {
    "CSV_EXPORT_FAILED",
    "RAW_EXPORT_FAILED",
    "RAW_PARSE_FAILED",
    "CSV_ANALYSIS_EXCEPTION",
    "ANALYSIS_EXCEPTION",
    "CSV_FILE_NOT_FOUND",
    "MISSING_REF_CHANNEL",
    "MISSING_CLK_PAIR",
    "MISSING_DATA_PAIR",
    "REF_NO_CLOCK",
}


def event_confirm_key(event):
    channel = str(event.get("channel", "")).upper().strip()
    event_type = str(event.get("event_type", "")).upper().strip()

    if "SSI_CLOCK" in channel or "CLOCK" in channel or "CLK" in channel:
        family = "SSI_CLOCK"
    elif "SSI_DATA" in channel or "DATA" in channel:
        family = "SSI_DATA"
    elif "CHANNEL 0" in channel or "REF" in channel:
        family = "CH0"
    else:
        family = channel or "GENERAL"

    return f"{family}:{event_type}"


class ClockAnalyzer:
    """
    CSV 기반 판정기.

    판정 방향:
    1) Ch0는 GUI 입력 기준 Hz와 비교한다.
    2) SSI CLOCK/DATA는 차동쌍을 수신기 관점으로 해석한다.
       - +와 -가 짧게 같은 상태가 되는 것은 edge skew로 보고 허용
       - 길게 같은 상태가 되면 수신기 undefined 가능성이 있어 NG
    3) SSI CLOCK/DATA의 정상 형태는 첫 번째 유효 샘플을 baseline으로 기억한다.
    """
    def __init__(self):
        self.baseline = None
        self.baseline_path = None

    def reset(self):
        self.baseline = None
        self.baseline_path = None

    def analyze(self, csv_path, ref_freq_hz, ref_tol_percent, auto_learn=True, session_dir=None):
        csv_path = Path(csv_path)

        if not csv_path.exists():
            return "NG", "raw data file not found", [{
                "channel": "",
                "event_type": "RAW_FILE_NOT_FOUND",
                "detail": str(csv_path),
            }]

        try:
            data = load_saleae_csv(csv_path)
            if data is None:
                return "NG", "raw data parse failed", [{
                    "channel": "",
                    "event_type": "RAW_PARSE_FAILED",
                    "detail": str(csv_path),
                }]

            t = data["time"]
            channels = data["channels"]
            events = []
            message_parts = []

            if CH_REF not in channels:
                events.append({"channel": f"Channel {CH_REF}", "event_type": "MISSING_REF_CHANNEL", "detail": "reference channel not found"})
            if CH_CLK_P not in channels or CH_CLK_N not in channels:
                events.append({"channel": "SSI CLOCK", "event_type": "MISSING_CLK_PAIR", "detail": "clock differential pair not found"})
            if CH_DATA_P not in channels or CH_DATA_N not in channels:
                events.append({"channel": "SSI DATA", "event_type": "MISSING_DATA_PAIR", "detail": "data differential pair not found"})

            if events:
                return "NG", "missing required channel", events

            # 1. Ch0 reference clock check
            ref_metrics, ref_events = analyze_reference_clock(
                t=t,
                v=channels[CH_REF],
                expected_hz=ref_freq_hz,
                tolerance_percent=ref_tol_percent,
            )
            events.extend(ref_events)
            message_parts.append(
                f"REF measured={ref_metrics.get('freq_hz', 0):.3f}Hz target={ref_freq_hz:.3f}Hz err={ref_metrics.get('error_percent', 0):.3f}%"
            )

            # 2. Differential pair receiver-view check
            clk_rx, clk_pair_metrics, clk_pair_events = reconstruct_diff_pair_receiver_view(
                t=t,
                p=channels[CH_CLK_P],
                n=channels[CH_CLK_N],
                pair_name="SSI_CLOCK",
            )
            data_rx, data_pair_metrics, data_pair_events = reconstruct_diff_pair_receiver_view(
                t=t,
                p=channels[CH_DATA_P],
                n=channels[CH_DATA_N],
                pair_name="SSI_DATA",
            )
            events.extend(clk_pair_events)
            events.extend(data_pair_events)

            message_parts.append(
                f"CLK diff_equal_max={clk_pair_metrics['max_equal_sec']*1e6:.3f}us"
            )
            message_parts.append(
                f"DATA diff_equal_max={data_pair_metrics['max_equal_sec']*1e6:.3f}us"
            )

            # 수신기 관점 신호 분석
            clk_metrics = analyze_ssi_clock_rx(t, clk_rx)
            data_metrics = analyze_ssi_data_rx(t, data_rx)

            message_parts.append(
                f"CLK half_med={clk_metrics.get('active_half_period_median_sec', 0)*1e6:.3f}us edges={clk_metrics.get('edge_count', 0)}"
            )
            message_parts.append(
                f"DATA edges={data_metrics.get('edge_count', 0)} max_stable={data_metrics.get('max_stable_sec', 0)*1e3:.3f}ms"
            )

            # 현재 샘플 자체가 명백히 깨졌으면 baseline으로 쓰지 않음
            if events:
                return "NG", " / ".join(message_parts), events

            current = {
                "ref": ref_metrics,
                "clk_pair": clk_pair_metrics,
                "data_pair": data_pair_metrics,
                "clk": clk_metrics,
                "data": data_metrics,
                "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            }

            # 3. Baseline learn or compare
            if auto_learn and self.baseline is None:
                # Internal reference learning only. Do not expose "baseline learned" on UI/log.
                self.baseline = current
                return "OK", " / ".join(message_parts), []

            if self.baseline is not None:
                cmp_events = compare_to_baseline(current, self.baseline)
                events.extend(cmp_events)

            if events:
                return "NG", " / ".join(message_parts), events

            return "OK", " / ".join(message_parts), []

        except Exception:
            return "NG", "raw data analysis exception", [{
                "channel": "",
                "event_type": "ANALYSIS_EXCEPTION",
                "detail": traceback.format_exc(),
            }]





def calculate_total_samples(total_seconds, sample_interval, capture_duration):
    """Return planned sample count.

    sample_interval > 0 : fixed schedule sampling every interval seconds.
    sample_interval == 0: continuous mode; next capture starts as soon as possible
                         after the previous capture command completes.
    """
    total_seconds = float(total_seconds)
    sample_interval = float(sample_interval)
    capture_duration = float(capture_duration)
    if total_seconds <= 0:
        return 0
    if sample_interval <= 0:
        return int(math.ceil(total_seconds / max(capture_duration, 1e-9)))
    return int(math.ceil(total_seconds / sample_interval))


class SaleaeMonitorWorker(QThread):
    log_signal = Signal(str)
    status_signal = Signal(str)
    count_signal = Signal(int, int, int, int)
    finished_signal = Signal()
    channel_status_signal = Signal(dict)
    phase_signal = Signal(str, float, float)
    schedule_signal = Signal(float, float, float, int)

    def __init__(self, config):
        super().__init__()
        self.config = config
        self.stop_event = threading.Event()
        self.current_capture = None
        self.current_capture_lock = threading.Lock()
        self.session_dir = None
        self.result_csv_path = None
        self.event_csv_path = None
        self.sample_count = 0
        self.ok_count = 0
        self.ng_count = 0
        self.total_samples = calculate_total_samples(config['total_seconds'], config['sample_interval'], config['capture_duration'])
        self.analyzer = ClockAnalyzer()
        self.export_threads = []
        self.analysis_queue = queue.Queue()
        self.analysis_thread = None
        self.result_lock = threading.Lock()
        self.count_lock = threading.Lock()
        self.soft_fail_counts = {}
        self.last_soft_keys = set()
        self.logic_watch_thread = None

    def stop(self):
        self.stop_event.set()
        with self.current_capture_lock:
            cap = self.current_capture
        if cap is not None:
            try:
                cap.stop()
                self.log_signal.emit('Current capture stop requested')
            except Exception as e:
                self.log_signal.emit(f'Current capture stop failed: {e}')

    def _call_with_timeout(self, func, timeout_sec, description):
        result_q = queue.Queue(maxsize=1)

        def runner():
            try:
                result_q.put((True, func()))
            except Exception as e:
                result_q.put((False, e))

        th = threading.Thread(target=runner, daemon=True)
        th.start()
        th.join(timeout_sec)
        if th.is_alive():
            raise TimeoutError(f'{description} timed out after {timeout_sec} sec')

        ok, value = result_q.get_nowait()
        if ok:
            return value
        raise value

    def _probe_automation_server(self):
        with automation.Manager.connect(port=PORT):
            return True

    def _connect_manager_with_timeout(self):
        return self._call_with_timeout(
            lambda: automation.Manager.connect(port=PORT),
            SALEAE_AUTOMATION_CALL_TIMEOUT_SEC,
            'Saleae Automation connection',
        )

    def _wait_for_saleae_device(self, manager):
        deadline = time.time() + SALEAE_DEVICE_READY_TIMEOUT_SEC
        logged_waiting = False
        last_error = None

        while time.time() < deadline:
            if self.stop_event.is_set():
                raise SaleaeConnectionError('Saleae connection canceled by user.')
            try:
                devices = self._call_with_timeout(
                    lambda: manager.get_devices(),
                    SALEAE_AUTOMATION_CALL_TIMEOUT_SEC,
                    'Saleae device detection',
                )
                if devices:
                    self.log_signal.emit('Device connected')
                    return devices
                if not logged_waiting:
                    self.log_signal.emit('Waiting for Saleae device connection...')
                    logged_waiting = True
            except Exception as e:
                last_error = e
                if not logged_waiting:
                    self.log_signal.emit('Waiting for Saleae device connection...')
                    logged_waiting = True
            time.sleep(SALEAE_DEVICE_POLL_INTERVAL_SEC)

        detail = f' Last error: {last_error}' if last_error else ''
        raise SaleaeConnectionError(
            f'Saleae device was not detected within {SALEAE_DEVICE_READY_TIMEOUT_SEC} sec. '
            f'Check USB connection and reconnect the Saleae device.{detail}'
        )

    def _is_logic_process_running(self):
        """Return True if Saleae Logic is already running on this Windows PC."""
        if os.name != 'nt':
            return False
        try:
            creationflags = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
            completed = subprocess.run(
                ['tasklist', '/FI', 'IMAGENAME eq Logic.exe', '/NH'],
                capture_output=True,
                text=True,
                timeout=5,
                creationflags=creationflags,
            )
            output = ((completed.stdout or '') + (completed.stderr or '')).lower()
            return 'logic.exe' in output
        except Exception:
            return False

    def _launch_logic_if_needed(self):
        # If Logic 2 is already running, do not launch another instance.
        # Starting a second Logic.exe can interfere with the Automation Server/device state.
        was_already_running = self._is_logic_process_running()
        if was_already_running:
            self.log_signal.emit('Saleae Logic already running')
        else:
            logic_path = None
            for candidate in LOGIC_EXE_CANDIDATES:
                if Path(candidate).exists():
                    logic_path = candidate
                    break

            if logic_path is None:
                raise SaleaeConnectionError(
                    'Saleae Logic executable was not found. '
                    'Please update LOGIC_EXE_CANDIDATES to match this PC.'
                )

            self.log_signal.emit('Starting Saleae Logic')
            try:
                subprocess.Popen([logic_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception as e:
                self.log_signal.emit(f'Failed to start Saleae Logic: {e}')

        deadline = time.time() + SALEAE_AUTOMATION_READY_TIMEOUT_SEC
        logged_waiting = False
        last_error = None

        while time.time() < deadline:
            if self.stop_event.is_set():
                raise SaleaeConnectionError('Saleae connection canceled by user.')
            try:
                self._call_with_timeout(
                    self._probe_automation_server,
                    SALEAE_AUTOMATION_CALL_TIMEOUT_SEC,
                    'Saleae Automation readiness check',
                )
                self.log_signal.emit('Saleae Automation connected')
                return was_already_running
            except Exception as e:
                last_error = e
                if not logged_waiting:
                    self.log_signal.emit('Waiting for Saleae Automation Server...')
                    logged_waiting = True
                time.sleep(1)

        raise SaleaeConnectionError(
            f'Failed to connect to Saleae Automation within {SALEAE_AUTOMATION_READY_TIMEOUT_SEC} sec. '
            'Check that Logic 2 is open and Automation Server is enabled. '
            f'Port: {PORT}. Last error: {last_error}'
        )

    def _start_existing_logic_watch(self):
        """Stop monitoring if the pre-existing Logic.exe process is closed by the user."""
        def watcher():
            was_seen_closed = False
            while not self.stop_event.is_set():
                time.sleep(1.0)
                if not self._is_logic_process_running():
                    if not was_seen_closed:
                        was_seen_closed = True
                        self.log_signal.emit('Saleae Logic was closed. Auto STOP requested.')
                    self.stop()
                    break

        th = threading.Thread(target=watcher, daemon=True)
        th.start()
        return th

    def _init_result_files(self, session_dir):
        self.result_csv_path = session_dir / RESULT_LOG_FILENAME
        self.event_csv_path = session_dir / EVENT_LOG_FILENAME

        with open(self.result_csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, delimiter='\t', lineterminator='\n')
            writer.writerow(['sample_no', 'timestamp', 'result', 'message', 'raw_path'])

        with open(self.event_csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, delimiter='\t', lineterminator='\n')
            writer.writerow(['sample_no', 'timestamp', 'channel', 'event_type', 'detail'])

    def _append_result(self, sample_no, result, message, csv_path=''):
        with self.result_lock:
            with open(self.result_csv_path, 'a', newline='', encoding='utf-8') as f:
                writer = csv.writer(f, delimiter='\t', lineterminator='\n')
                writer.writerow([
                    sample_no,
                    datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                    result,
                    message,
                    str(csv_path) if csv_path else '',
                ])

    def _append_events(self, sample_no, events):
        if not events:
            return
        with self.result_lock:
            with open(self.event_csv_path, 'a', newline='', encoding='utf-8') as f:
                writer = csv.writer(f, delimiter='\t', lineterminator='\n')
                for ev in events:
                    writer.writerow([
                        sample_no,
                        datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                        ev.get('channel', ''),
                        ev.get('event_type', ''),
                        ev.get('detail', ''),
                    ])

    def _build_channel_status(self, result, events):
        status = {
            'ch0': {'title': 'Ch0', 'subtitle': 'FREQ', 'value': 'PASS' if result == 'OK' else 'CHECK', 'accent': 'neutral'},
            'clk': {'title': 'Ch1/2', 'subtitle': 'CLK±', 'value': 'PASS' if result == 'OK' else 'CHECK', 'accent': 'neutral'},
            'data': {'title': 'Ch3/4', 'subtitle': 'DAT±', 'value': 'PASS' if result == 'OK' else 'CHECK', 'accent': 'neutral'},
        }

        if result == 'OK':
            status['ch0']['accent'] = 'ok'
            status['clk']['accent'] = 'ok'
            status['data']['accent'] = 'ok'
            return status

        status['ch0']['value'] = 'FAIL'
        status['clk']['value'] = 'FAIL'
        status['data']['value'] = 'FAIL'
        status['ch0']['accent'] = 'ng'
        status['clk']['accent'] = 'ng'
        status['data']['accent'] = 'ng'

        if not events:
            return status

        affected = {'ch0': False, 'clk': False, 'data': False}
        for ev in events:
            ch = (ev.get('channel') or '').upper()
            if 'CHANNEL 0' in ch or 'REF' in ch:
                affected['ch0'] = True
            if 'CLOCK' in ch or 'CLK' in ch:
                affected['clk'] = True
            if 'DATA' in ch:
                affected['data'] = True

        for key, present in affected.items():
            if not present:
                status[key]['value'] = 'PASS'
                status[key]['accent'] = 'ok'

        return status

    def _increment_result_count(self, result):
        with self.count_lock:
            if result == 'OK':
                self.ok_count += 1
            else:
                self.ng_count += 1
            ok = self.ok_count
            ng = self.ng_count
            samples = self.sample_count
        self.count_signal.emit(samples, ok, ng, self.total_samples)

    def _export_worker(self, capture, sample_no, raw_data_path, temp_export_dir, scheduled_time, config):
        raw_path = raw_data_path
        try:
            temp_export_dir.mkdir(parents=True, exist_ok=True)
            raw_data_path.parent.mkdir(parents=True, exist_ok=True)

            self.log_signal.emit(f'#{sample_no} exporting raw data')
            capture.export_raw_data_csv(
                directory=str(temp_export_dir),
                digital_channels=FIXED_CHANNELS,
                iso8601_timestamp=False,
            )

            exported_csv = temp_export_dir / 'digital.csv'
            if not exported_csv.exists():
                raise FileNotFoundError(f'Exported raw CSV not found: {exported_csv}')

            if raw_data_path.exists():
                raw_data_path.unlink()

            rows_written, original_rows = compact_saleae_csv_to_txt(
                exported_csv,
                raw_data_path,
                required_channels=FIXED_CHANNELS,
            )
            self.log_signal.emit(
                f'#{sample_no} raw data saved as compact TXT ({rows_written} rows from {original_rows})'
            )

            try:
                shutil.rmtree(temp_export_dir)
            except Exception:
                pass

            self.analysis_queue.put({
                'sample_no': sample_no,
                'csv_path': raw_path,
                'scheduled_time': scheduled_time,
                'error': None,
            })
        except Exception:
            err = traceback.format_exc()
            try:
                raw_data_path.parent.mkdir(parents=True, exist_ok=True)
                (raw_data_path.parent / f'sample_{sample_no:04d}_export_error.txt').write_text(err, encoding='utf-8')
            except Exception:
                pass
            self.analysis_queue.put({
                'sample_no': sample_no,
                'csv_path': raw_path,
                'scheduled_time': scheduled_time,
                'error': err,
            })
        finally:
            try:
                capture.close()
            except Exception as e:
                self.log_signal.emit(f'capture.close failed: {e}')

    def _apply_transient_gate(self, result, message, events):
        """
        Convert one-off SSI waveform abnormalities into PASS-level observations.
        A FAIL is produced only after the same abnormality repeats for
        SOFT_FAIL_CONFIRM_COUNT consecutive analyzed samples.
        """
        if result == 'OK' or not events:
            self.soft_fail_counts.clear()
            self.last_soft_keys = set()
            return result, message, events

        immediate_events = []
        soft_events = []
        for ev in events:
            if str(ev.get('event_type', '')).upper() in IMMEDIATE_FAIL_EVENT_TYPES:
                immediate_events.append(ev)
            else:
                soft_events.append(ev)

        if immediate_events:
            self.soft_fail_counts.clear()
            self.last_soft_keys = set()
            return result, message, events

        current_keys = {event_confirm_key(ev) for ev in soft_events}

        # Consecutive-repeat confirmation: if a key disappears, its counter resets.
        for key in list(self.soft_fail_counts.keys()):
            if key not in current_keys:
                self.soft_fail_counts.pop(key, None)

        for key in current_keys:
            self.soft_fail_counts[key] = self.soft_fail_counts.get(key, 0) + 1

        max_count = max([self.soft_fail_counts.get(k, 0) for k in current_keys], default=0)

        if max_count >= SOFT_FAIL_CONFIRM_COUNT:
            confirmed = []
            for ev in soft_events:
                key = event_confirm_key(ev)
                ev2 = dict(ev)
                ev2['detail'] = f"confirmed_count={self.soft_fail_counts.get(key, 0)}, " + str(ev.get('detail', ''))
                confirmed.append(ev2)
            return 'NG', f'Confirmed signal abnormality repeated {max_count} times', confirmed

        observed = []
        for ev in soft_events:
            key = event_confirm_key(ev)
            ev2 = dict(ev)
            ev2['event_type'] = 'TRANSIENT_OBSERVATION_' + str(ev.get('event_type', '')).upper()
            ev2['detail'] = (
                f"not_confirmed_count={self.soft_fail_counts.get(key, 0)}, "
                f"confirm_required={SOFT_FAIL_CONFIRM_COUNT}, "
                + str(ev.get('detail', ''))
            )
            observed.append(ev2)

        return 'OK', f'PASS - transient observation not confirmed ({max_count}/{SOFT_FAIL_CONFIRM_COUNT})', observed

    def _analysis_loop(self, config):
        pending = {}
        next_no = 1

        def process_item(item):
            sample_no = item['sample_no']
            csv_path = item['csv_path']

            if item.get('error'):
                result = 'NG'
                message = 'Raw export failed'
                events = [{
                    'channel': '',
                    'event_type': 'RAW_EXPORT_FAILED',
                    'detail': item.get('error') or '',
                }]
            else:
                self.log_signal.emit(f'#{sample_no} analyzing')
                result, message, events = self.analyzer.analyze(
                    csv_path=csv_path,
                    ref_freq_hz=config['ref_freq_hz'],
                    ref_tol_percent=config['ref_tol_percent'],
                    auto_learn=config['auto_learn_ssi'],
                    session_dir=self.session_dir,
                )

            result, message, events = self._apply_transient_gate(result, message, events)

            if result == 'OK':
                self.log_signal.emit(f'#{sample_no} PASS')
            else:
                self.log_signal.emit(f'#{sample_no} FAIL - {message}')

            self._append_result(sample_no, result, message, csv_path)
            self._append_events(sample_no, events)
            self._increment_result_count(result)
            self.channel_status_signal.emit(self._build_channel_status(result, events))

        while True:
            item = self.analysis_queue.get()
            if item is None:
                break

            pending[item['sample_no']] = item
            while next_no in pending:
                process_item(pending.pop(next_no))
                next_no += 1

        # Final drain. This prevents a missing/failed early sample from blocking later samples forever.
        for sample_no in sorted(pending):
            process_item(pending[sample_no])

    def run(self):
        config = self.config
        session_name = f"{config['test_name']}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        self.session_dir = config['output_root'] / session_name
        self.session_dir.mkdir(parents=True, exist_ok=True)
        self._init_result_files(self.session_dir)

        total_seconds = config['total_seconds']
        sample_interval = config['sample_interval']
        capture_duration = config['capture_duration']

        start_time = None
        end_time = None

        self.log_signal.emit('Test started')
        self.log_signal.emit(f'Result folder: {self.session_dir}')
        self.log_signal.emit(f'Input Signal: {config["ref_freq_hz"]} Hz')
        self.count_signal.emit(self.sample_count, self.ok_count, self.ng_count, self.total_samples)
        self.channel_status_signal.emit({
            'ch0': {'title': 'Ch0', 'subtitle': 'FREQ', 'value': '—', 'accent': 'idle'},
            'clk': {'title': 'Ch1/2', 'subtitle': 'CLK±', 'value': '—', 'accent': 'idle'},
            'data': {'title': 'Ch3/4', 'subtitle': 'DAT±', 'value': '—', 'accent': 'idle'},
        })

        self.analysis_thread = threading.Thread(target=self._analysis_loop, args=(config,), daemon=True)
        self.analysis_thread.start()

        try:
            self.status_signal.emit('Starting Saleae')
            watch_existing_logic = self._launch_logic_if_needed()
            if watch_existing_logic:
                self.logic_watch_thread = self._start_existing_logic_watch()

            device_configuration = automation.LogicDeviceConfiguration(
                enabled_digital_channels=FIXED_CHANNELS,
                digital_sample_rate=FIXED_SAMPLE_RATE,
                digital_threshold_volts=FIXED_THRESHOLD,
            )

            manager_ctx = self._connect_manager_with_timeout()
            with manager_ctx as manager:
                if FIXED_DEVICE_ID:
                    device_id = FIXED_DEVICE_ID
                else:
                    devices = self._wait_for_saleae_device(manager)
                    device_id = devices[0].device_id

                start_time = time.time()
                end_time = start_time + total_seconds

                def start_one_sample(sample_no, scheduled_time):
                    raw_dir = self.session_dir / 'raw_data'
                    temp_export_dir = self.session_dir / '_export_tmp' / f'sample_{sample_no:04d}'
                    raw_csv_path = raw_dir / f'sample_{sample_no:04d}{RAW_DATA_EXT}'
                    raw_dir.mkdir(parents=True, exist_ok=True)

                    self.status_signal.emit(f'Sampling #{sample_no}')
                    self.log_signal.emit(f'#{sample_no} sampling started')
                    self.phase_signal.emit('capture', time.time(), capture_duration)

                    capture_configuration = automation.CaptureConfiguration(
                        buffer_size_megabytes=FIXED_BUFFER_MB,
                        capture_mode=automation.TimedCaptureMode(duration_seconds=capture_duration),
                    )

                    try:
                        capture = manager.start_capture(
                            device_id=device_id,
                            device_configuration=device_configuration,
                            capture_configuration=capture_configuration,
                        )

                        with self.current_capture_lock:
                            self.current_capture = capture

                        try:
                            capture.wait()
                        finally:
                            with self.current_capture_lock:
                                self.current_capture = None

                        # Saleae Logic 2 exports raw data only after the capture is complete.
                        # Keep one Saleae capture/session open at a time: export and close
                        # the finished capture before starting the next one. Analysis still
                        # runs asynchronously after the compact TXT is produced.
                        self._export_worker(capture, sample_no, raw_csv_path, temp_export_dir, scheduled_time, config)

                    except Exception:
                        err = traceback.format_exc()
                        err_path = raw_dir / f'sample_{sample_no:04d}_capture_error.txt'
                        err_path.write_text(err, encoding='utf-8')
                        self.analysis_queue.put({
                            'sample_no': sample_no,
                            'csv_path': raw_csv_path,
                            'scheduled_time': scheduled_time,
                            'error': err,
                        })
                        self.log_signal.emit(f'Sample {sample_no} capture failed - {err_path}')

                if sample_interval <= 0:
                    # Continuous mode: no scheduled wait. Start the next capture as soon
                    # as the previous capture command completes. CSV export/analysis still
                    # run in background threads.
                    self.schedule_signal.emit(start_time, end_time, 0.0, self.total_samples)
                    while not self.stop_event.is_set() and self.sample_count < self.total_samples:
                        self.sample_count += 1
                        sample_no = self.sample_count
                        self.count_signal.emit(self.sample_count, self.ok_count, self.ng_count, self.total_samples)
                        start_one_sample(sample_no, time.time())
                else:
                    slot_index = 0
                    self.schedule_signal.emit(start_time, end_time, start_time + sample_interval, self.total_samples)

                    while not self.stop_event.is_set() and slot_index < self.total_samples:
                        now = time.time()
                        if now >= end_time:
                            break

                        scheduled_time = start_time + slot_index * sample_interval
                        wait_sec = scheduled_time - now
                        if wait_sec > 0:
                            self.status_signal.emit('Waiting')
                            self.phase_signal.emit('wait', time.time(), wait_sec)
                            if self.stop_event.wait(wait_sec):
                                break

                        if time.time() >= end_time:
                            break

                        # If capture itself overruns the fixed schedule, skip missed slots silently.
                        now_for_slot = time.time()
                        while start_time + slot_index * sample_interval < now_for_slot - 0.001 and slot_index > self.sample_count:
                            slot_index += 1

                        self.sample_count += 1
                        sample_no = self.sample_count
                        self.count_signal.emit(self.sample_count, self.ok_count, self.ng_count, self.total_samples)
                        self.schedule_signal.emit(start_time, end_time, start_time + (slot_index + 1) * sample_interval, self.total_samples)

                        start_one_sample(sample_no, scheduled_time)

                        slot_index += 1
                        next_slot = slot_index
                        now_after_capture = time.time()
                        while start_time + next_slot * sample_interval <= now_after_capture and next_slot < self.total_samples:
                            next_slot += 1
                        # Do not move slot_index past the next slot unless capture itself already overran.
                        slot_index = max(slot_index, min(next_slot, self.total_samples))
                        next_target = start_time + slot_index * sample_interval
                        self.schedule_signal.emit(start_time, end_time, next_target, self.total_samples)

                self.phase_signal.emit('idle', 0, 0)

                # Keep the Saleae automation manager alive until all export tasks are done.
                if self.export_threads:
                    self.status_signal.emit('Finalizing')
                    for th in list(self.export_threads):
                        th.join()

            # Now no more CSV files will be produced. Finish analysis.
            self.analysis_queue.put(None)
            if self.analysis_thread:
                self.analysis_thread.join()

            self.status_signal.emit('Finished')

        except SaleaeConnectionError as e:
            if self.session_dir:
                err_path = self.session_dir / 'saleae_connection_error.txt'
                err_path.write_text(str(e), encoding='utf-8')
                self.log_signal.emit(f'Saleae connection error: {e}')
                self.log_signal.emit(f'Error detail saved: {err_path}')
            else:
                self.log_signal.emit(f'Saleae connection error: {e}')
            self.stop_event.set()
            self.status_signal.emit('Stopped')

        except Exception:
            err = traceback.format_exc()
            if self.session_dir:
                err_path = self.session_dir / 'fatal_error.txt'
                err_path.write_text(err, encoding='utf-8')
                self.log_signal.emit(f'Fatal error: {err_path}')
            else:
                self.log_signal.emit(f'Fatal error: {err}')
            self.status_signal.emit('Fatal error')

        finally:
            with self.current_capture_lock:
                self.current_capture = None
            if self.stop_event.is_set():
                self.status_signal.emit('Stopped')
            self.phase_signal.emit('idle', 0, 0)
            self.log_signal.emit('Monitoring finished')
            self.finished_signal.emit()


