class SegmentedProgressBar(QWidget):
    def __init__(self):
        super().__init__()
        self.total = 1
        self.current = 0
        self.setMinimumHeight(16)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def set_values(self, current, total):
        self.current = max(0, int(current))
        self.total = max(1, int(total))
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, False)
        rect = self.rect().adjusted(0, 2, 0, -2)

        # background
        painter.fillRect(rect, QColor('#eeeeee'))
        painter.setPen(QPen(QColor('#c2c2c2')))
        painter.drawRect(rect.adjusted(0, 0, -1, -1))

        # filled portion by completed sample count
        fill_ratio = min(1.0, self.current / max(1, self.total))
        fill_width = int(rect.width() * fill_ratio)
        if fill_width > 0:
            painter.fillRect(rect.left() + 1, rect.top() + 1, max(0, fill_width - 1), rect.height() - 1, QColor('#2f6db3'))

        # segment ticks. Show every target sample when <=120, otherwise compress to 60 visible ticks.
        tick_count = self.total if self.total <= 120 else 60
        tick_color = QColor('#ffffff') if fill_width > 0 else QColor('#c8c8c8')
        painter.setPen(QPen(QColor('#c8c8c8')))
        for i in range(1, tick_count):
            x = rect.left() + int(rect.width() * i / tick_count)
            painter.drawLine(x, rect.top() + 1, x, rect.bottom() - 1)

        # completed boundary marker
        if self.current > 0 and self.current < self.total:
            x = rect.left() + int(rect.width() * fill_ratio)
            painter.setPen(QPen(QColor('#1d1d1d')))
            painter.drawLine(x, rect.top(), x, rect.bottom())

        painter.end()


class ToggleSwitch(QCheckBox):
    """Small ON/OFF toggle switch used for scheduled start enable."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(SCHEDULE_SWITCH_WIDTH, 24)
        self.setCursor(Qt.PointingHandCursor)
        self.setText('')
        self.setToolTip("Enable Start/Stop scheduling. The schedule uses this PC's Windows local date/time.")

    def hitButton(self, pos):
        # Treat the whole visual switch rectangle as the clickable button area.
        return self.isEnabled() and self.rect().contains(pos)

    def mousePressEvent(self, event):
        # When a run or scheduled plan is active, the switch is disabled and
        # must not toggle even if the user clicks the painted switch body.
        if not self.isEnabled():
            event.ignore()
            return
        if event.button() == Qt.LeftButton and self.rect().contains(event.pos()):
            self.setChecked(not self.isChecked())
            event.accept()
            return
        super().mousePressEvent(event)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        rect = self.rect().adjusted(1, 3, -1, -3)
        radius = rect.height() / 2

        if self.isChecked():
            bg = QColor('#2565ad')
            handle = QColor('#ffffff')
            text = 'ON'
            text_color = QColor('#ffffff')
            knob_x = rect.right() - rect.height() + 2
            text_rect = rect.adjusted(6, 0, -20, 0)
        else:
            bg = QColor('#d3d3d3')
            handle = QColor('#ffffff')
            text = 'OFF'
            text_color = QColor('#555555')
            knob_x = rect.left() + 2
            text_rect = rect.adjusted(18, 0, -4, 0)

        if not self.isEnabled():
            bg = QColor('#c6c6c6')
            handle = QColor('#eeeeee')
            text_color = QColor('#8a8a8a')

        painter.setPen(QPen(QColor('#9d9d9d')))
        painter.setBrush(bg)
        painter.drawRoundedRect(rect, radius, radius)

        painter.setPen(text_color)
        font = QFont('Arial', 7)
        font.setBold(True)
        painter.setFont(font)
        painter.drawText(text_rect, Qt.AlignCenter, text)

        knob = rect.adjusted(0, 0, 0, 0)
        knob.setLeft(int(knob_x))
        knob.setRight(int(knob_x + rect.height() - 4))
        knob.setTop(rect.top() + 2)
        knob.setBottom(rect.bottom() - 2)
        painter.setPen(QPen(QColor('#8f8f8f')))
        painter.setBrush(handle)
        painter.drawEllipse(knob)
        painter.end()


class ScheduleDateTimePicker(QWidget):
    """Date/time field with a calendar popup and explicit hour/min/sec inputs."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._dt = QDateTime.currentDateTime().addSecs(60)
        self._popup = None
        self.setMinimumWidth(SCHEDULE_TIME_EDIT_WIDTH)
        self.setFixedHeight(28)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)

        self.line = QLineEdit()
        self.line.setObjectName('fieldEdit')
        self.line.setReadOnly(True)
        self.line.setCursor(Qt.PointingHandCursor)
        self.line.setFixedHeight(28)
        self.line.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.line.mousePressEvent = self._line_clicked
        lay.addWidget(self.line, 1)

        self.drop_btn = QPushButton('▾')
        self.drop_btn.setObjectName('calendarDropButton')
        self.drop_btn.setFixedSize(24, 28)
        self.drop_btn.clicked.connect(self.show_popup)
        lay.addWidget(self.drop_btn)
        self._update_text()

    def _line_clicked(self, event):
        self.show_popup()
        event.accept()

    def dateTime(self):
        return QDateTime(self._dt)

    def setDateTime(self, qdt):
        self._dt = QDateTime(qdt)
        self._update_text()

    def setEnabled(self, enabled):
        super().setEnabled(enabled)
        self.line.setEnabled(enabled)
        self.drop_btn.setEnabled(enabled)

    def _update_text(self):
        self.line.setText(self._dt.toString('yyyy-MM-dd HH:mm:ss'))

    def _on_date_selected(self, qdate):
        t = self._dt.time()
        self._dt = QDateTime(qdate, t)
        self._update_text()

    def _on_time_changed(self):
        if not self._popup:
            return
        date = self._dt.date()
        hour = self.hour_spin.value()
        minute = self.minute_spin.value()
        second = self.second_spin.value()
        self._dt = QDateTime(date, QTime(hour, minute, second))
        self._update_text()

    def show_popup(self):
        if self._popup and self._popup.isVisible():
            self._popup.close()
            return

        popup = QFrame(None, Qt.Popup)
        popup.setObjectName('schedulePopup')
        popup.setWindowFlag(Qt.FramelessWindowHint, True)
        popup.setMinimumWidth(310)
        popup_l = QVBoxLayout(popup)
        popup_l.setContentsMargins(8, 8, 8, 8)
        popup_l.setSpacing(8)

        self.calendar = QCalendarWidget()
        self.calendar.setObjectName('scheduleCalendar')
        self.calendar.setGridVisible(True)
        self.calendar.setSelectedDate(self._dt.date())
        self.calendar.clicked.connect(self._on_date_selected)
        popup_l.addWidget(self.calendar)

        time_row = QHBoxLayout()
        time_row.setContentsMargins(0, 0, 0, 0)
        time_row.setSpacing(6)

        self.hour_spin = QSpinBox()
        self.hour_spin.setRange(0, 23)
        self.hour_spin.setValue(self._dt.time().hour())
        self.hour_spin.setFixedWidth(48)
        self.hour_spin.setObjectName('timeSpin')
        self.hour_spin.valueChanged.connect(self._on_time_changed)

        self.minute_spin = QSpinBox()
        self.minute_spin.setRange(0, 59)
        self.minute_spin.setValue(self._dt.time().minute())
        self.minute_spin.setFixedWidth(48)
