class ScheduleWindowEditDialog(QDialog):
    """Edit one Start/Stop schedule window in a side-by-side popup."""

    def __init__(self, parent=None, start_dt=None, stop_dt=None):
        super().__init__(parent)
        self.setWindowTitle('Schedule Window')
        self.setModal(True)
        self.resize(860, 560)
        self._updating = False
        now = datetime.now().replace(microsecond=0) + timedelta(minutes=1)
        self._initial_start = start_dt or now
        self._initial_stop = stop_dt or (self._initial_start + timedelta(hours=1))
        if self._initial_stop <= self._initial_start:
            self._initial_stop = self._initial_start + timedelta(hours=1)
        self._build_ui()
        self._set_start_dt(self._initial_start)
        self._set_stop_dt(self._initial_stop)
        self._set_duration_from_start_stop()

    def _build_ui(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(12, 12, 12, 12)
        root.setSpacing(10)

        title = QLabel('Set Start and Stop time for this schedule window.')
        title.setObjectName('subtleLabel')
        root.addWidget(title)

        top = QHBoxLayout()
        top.setContentsMargins(0, 0, 0, 0)
        top.setSpacing(10)

        start_panel = self._make_datetime_panel('Start')
        stop_panel = self._make_datetime_panel('Stop')

        arrow = QLabel('→')
        arrow.setObjectName('scheduleArrowLabel')
        arrow.setAlignment(Qt.AlignCenter)
        arrow.setFixedWidth(36)

        top.addWidget(start_panel, 1)
        top.addWidget(arrow, 0, Qt.AlignCenter)
        top.addWidget(stop_panel, 1)
        root.addLayout(top, 1)

        duration_row = QHBoxLayout()
        duration_row.setContentsMargins(0, 0, 0, 0)
        duration_row.setSpacing(8)
        duration_row.addStretch(1)
        duration_label = QLabel('Duration :')
        duration_label.setObjectName('fieldLabel')
        duration_row.addWidget(duration_label)
        self.duration_spin = QSpinBox()
        self.duration_spin.setObjectName('durationSpin')
        self.duration_spin.setRange(1, 100000)
        self.duration_spin.setFixedWidth(96)
        self.duration_spin.valueChanged.connect(self._on_duration_changed)
        duration_row.addWidget(self.duration_spin)
        duration_unit = QLabel('min')
        duration_unit.setObjectName('suffixLabel')
        duration_row.addWidget(duration_unit)
        duration_row.addStretch(1)
        root.addLayout(duration_row)

        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(self._accept_checked)
        buttons.rejected.connect(self.reject)
        root.addWidget(buttons)

    def _make_datetime_panel(self, title):
        panel = QFrame()
        panel.setObjectName('scheduleEditPanel')
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(8, 8, 8, 8)
        lay.setSpacing(8)

        lbl = QLabel(title)
        lbl.setObjectName('schedulePanelTitle')
        lbl.setAlignment(Qt.AlignCenter)
        lay.addWidget(lbl)

        cal = QCalendarWidget()
        cal.setObjectName('scheduleCalendar')
        cal.setGridVisible(True)
        lay.addWidget(cal, 1)

        time_row = QHBoxLayout()
        time_row.setContentsMargins(0, 0, 0, 0)
        time_row.setSpacing(6)

        hour = QSpinBox()
        hour.setRange(0, 23)
        hour.setFixedWidth(48)
        hour.setObjectName('timeSpin')
        minute = QSpinBox()
        minute.setRange(0, 59)
        minute.setFixedWidth(48)
        minute.setObjectName('timeSpin')
        second = QSpinBox()
        second.setRange(0, 59)
        second.setFixedWidth(48)
        second.setObjectName('timeSpin')

        for spin, unit in [(hour, '시'), (minute, '분'), (second, '초')]:
            time_row.addWidget(spin)
            unit_lbl = QLabel(unit)
            unit_lbl.setObjectName('suffixLabel')
            time_row.addWidget(unit_lbl)
        time_row.addStretch(1)
        lay.addLayout(time_row)

        if title == 'Start':
            self.start_calendar = cal
            self.start_hour_spin = hour
            self.start_minute_spin = minute
            self.start_second_spin = second
            cal.selectionChanged.connect(self._on_start_changed)
            hour.valueChanged.connect(self._on_start_changed)
            minute.valueChanged.connect(self._on_start_changed)
            second.valueChanged.connect(self._on_start_changed)
        else:
            self.stop_calendar = cal
            self.stop_hour_spin = hour
            self.stop_minute_spin = minute
            self.stop_second_spin = second
            cal.selectionChanged.connect(self._on_stop_changed)
            hour.valueChanged.connect(self._on_stop_changed)
            minute.valueChanged.connect(self._on_stop_changed)
            second.valueChanged.connect(self._on_stop_changed)

        return panel

    def _get_start_dt(self):
        qd = self.start_calendar.selectedDate()
        qt = QTime(self.start_hour_spin.value(), self.start_minute_spin.value(), self.start_second_spin.value())
        return QDateTime(qd, qt).toPython().replace(microsecond=0)

    def _get_stop_dt(self):
        qd = self.stop_calendar.selectedDate()
        qt = QTime(self.stop_hour_spin.value(), self.stop_minute_spin.value(), self.stop_second_spin.value())
        return QDateTime(qd, qt).toPython().replace(microsecond=0)

    def _set_start_dt(self, dt):
        self._updating = True
        qdt = QDateTime.fromString(dt.strftime('%Y-%m-%d %H:%M:%S'), 'yyyy-MM-dd HH:mm:ss')
        self.start_calendar.setSelectedDate(qdt.date())
        self.start_hour_spin.setValue(qdt.time().hour())
        self.start_minute_spin.setValue(qdt.time().minute())
        self.start_second_spin.setValue(qdt.time().second())
        self._updating = False

    def _set_stop_dt(self, dt):
        self._updating = True
        qdt = QDateTime.fromString(dt.strftime('%Y-%m-%d %H:%M:%S'), 'yyyy-MM-dd HH:mm:ss')
        self.stop_calendar.setSelectedDate(qdt.date())
        self.stop_hour_spin.setValue(qdt.time().hour())
        self.stop_minute_spin.setValue(qdt.time().minute())
        self.stop_second_spin.setValue(qdt.time().second())
        self._updating = False

    def _set_duration_from_start_stop(self):
        start_dt = self._get_start_dt()
        stop_dt = self._get_stop_dt()
        minutes = max(1, int(round((stop_dt - start_dt).total_seconds() / 60.0)))
        self._updating = True
        self.duration_spin.setValue(minutes)
        self._updating = False

    def _on_start_changed(self):
        if self._updating:
            return
        start_dt = self._get_start_dt()
        stop_dt = start_dt + timedelta(minutes=self.duration_spin.value())
        self._set_stop_dt(stop_dt)

    def _on_stop_changed(self):
        if self._updating:
            return
        start_dt = self._get_start_dt()
        stop_dt = self._get_stop_dt()
        if stop_dt > start_dt:
            self._set_duration_from_start_stop()

    def _on_duration_changed(self):
        if self._updating:
            return
        start_dt = self._get_start_dt()
        stop_dt = start_dt + timedelta(minutes=self.duration_spin.value())
        self._set_stop_dt(stop_dt)

    def _accept_checked(self):
        start_dt = self.start_datetime()
        stop_dt = self.stop_datetime()
        if stop_dt <= start_dt:
            QMessageBox.critical(self, 'Schedule Error', 'Stop time must be later than Start time.')
            return
        self.accept()

    def start_datetime(self):
        return self._get_start_dt()

    def stop_datetime(self):
        return self._get_stop_dt()


class SchedulePlanDialog(QDialog):
    """Popup dialog for multiple Start/Stop schedule pairs."""

    def __init__(self, parent=None, schedules=None):
        super().__init__(parent)
        self.setWindowTitle('Start / Stop Schedule Settings')
        self.resize(760, 400)
        self.setModal(True)
        self._schedule_rows = []
        self._build_ui()
        schedules = schedules or []
        if schedules:
            self._schedule_rows = [(s.replace(microsecond=0), e.replace(microsecond=0)) for s, e in schedules]
        else:
            now = datetime.now().replace(microsecond=0) + timedelta(minutes=1)
            self._schedule_rows = [(now, now + timedelta(hours=1))]
        self._refresh_table()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(8)

        desc = QLabel('Set one or more Windows-local Start/Stop time windows. Double-click a row, or press Add Window, to edit Start/Stop together.')
        desc.setWordWrap(True)
        desc.setObjectName('subtleLabel')
        layout.addWidget(desc)

        self.table = QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(['No', 'Start', 'Stop'])
        self.table.verticalHeader().setVisible(False)
        self.table.setSelectionBehavior(QTableWidget.SelectRows)
        self.table.setSelectionMode(QTableWidget.SingleSelection)
        self.table.setEditTriggers(QTableWidget.NoEditTriggers)
        self.table.cellDoubleClicked.connect(self._edit_row)
        self.table.horizontalHeader().setSectionResizeMode(0, QHeaderView.Fixed)
        self.table.horizontalHeader().resizeSection(0, 52)
        self.table.horizontalHeader().setSectionResizeMode(1, QHeaderView.Stretch)
        self.table.horizontalHeader().setSectionResizeMode(2, QHeaderView.Stretch)
        layout.addWidget(self.table, 1)

        button_row = QHBoxLayout()
        add_btn = QPushButton('Add Window')
        add_btn.clicked.connect(self._add_default_row)
        edit_btn = QPushButton('Edit Selected')
        edit_btn.clicked.connect(self._edit_selected_row)
        del_btn = QPushButton('Delete Selected')
        del_btn.clicked.connect(self._delete_selected_row)
        button_row.addWidget(add_btn)
        button_row.addWidget(edit_btn)
        button_row.addWidget(del_btn)
        button_row.addStretch(1)
        layout.addLayout(button_row)

        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)

    def _refresh_table(self):
        self.table.setRowCount(0)
        for row, (start_dt, stop_dt) in enumerate(self._schedule_rows):
            self.table.insertRow(row)
            self.table.setRowHeight(row, 32)
            values = [str(row + 1), start_dt.strftime('%Y-%m-%d %H:%M:%S'), stop_dt.strftime('%Y-%m-%d %H:%M:%S')]
            for col, value in enumerate(values):
                item = QTableWidgetItem(value)
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                if col == 0:
                    item.setTextAlignment(Qt.AlignCenter)
                else:
                    item.setTextAlignment(Qt.AlignVCenter | Qt.AlignLeft)
                self.table.setItem(row, col, item)
        if self.table.rowCount() > 0 and self.table.currentRow() < 0:
            self.table.selectRow(0)

    def _add_default_row(self):
        if self._schedule_rows:
            last_stop = max(stop for _, stop in self._schedule_rows)
            start = max(last_stop + timedelta(minutes=1), datetime.now().replace(microsecond=0) + timedelta(minutes=1))
        else:
            start = datetime.now().replace(microsecond=0) + timedelta(minutes=1)
        stop = start + timedelta(hours=1)
        dlg = ScheduleWindowEditDialog(self, start, stop)
        if dlg.exec() == QDialog.Accepted:
            self._schedule_rows.append((dlg.start_datetime(), dlg.stop_datetime()))
            self._refresh_table()
            self.table.selectRow(self.table.rowCount() - 1)

    def _edit_selected_row(self):
        row = self.table.currentRow()
        if row >= 0:
            self._edit_row(row, 0)

    def _edit_row(self, row, col):
        if row < 0 or row >= len(self._schedule_rows):
            return
        start_dt, stop_dt = self._schedule_rows[row]
        dlg = ScheduleWindowEditDialog(self, start_dt, stop_dt)
        if dlg.exec() == QDialog.Accepted:
            self._schedule_rows[row] = (dlg.start_datetime(), dlg.stop_datetime())
            self._refresh_table()
            self.table.selectRow(row)

    def _delete_selected_row(self):
        row = self.table.currentRow()
        if row >= 0 and row < len(self._schedule_rows):
            del self._schedule_rows[row]
            self._refresh_table()
            if self.table.rowCount() > 0:
                self.table.selectRow(min(row, self.table.rowCount() - 1))

    def schedules(self):
        out = []
        for row, (start_dt, stop_dt) in enumerate(self._schedule_rows):
            start_dt = start_dt.replace(microsecond=0)
            stop_dt = stop_dt.replace(microsecond=0)
            if stop_dt <= start_dt:
                raise ValueError(f'Schedule row {row + 1}: Stop time must be later than Start time.')
            out.append((start_dt, stop_dt))
        out.sort(key=lambda x: x[0])
        for idx in range(1, len(out)):
            if out[idx][0] < out[idx - 1][1]:
                raise ValueError(f'Schedule row {idx + 1}: schedule windows must not overlap.')
        return out


