def compact_saleae_csv_to_txt(csv_path, txt_path, required_channels=None):
    """Convert Saleae digital.csv to a compact, Notepad-readable raw text file.

    Format:
      # metadata lines
      time_s<TAB>state
      0.000000000<TAB>01010

    The state string follows the channel order listed in the # channels line.
    Consecutive duplicate states are skipped, so sample-based exports shrink
    significantly while edge-based exports remain fully readable.
    """
    csv_path = Path(csv_path)
    txt_path = Path(txt_path)
    required_channels = list(required_channels or FIXED_CHANNELS)

    with open(csv_path, 'r', encoding='utf-8-sig', newline='') as f:
        reader = csv.reader(f)
        header = next(reader)
        time_idx = find_time_column(header)
        detected_indices = {}
        for idx, name in enumerate(header):
            if idx == time_idx:
                continue
            ch = parse_channel_number(name)
            if ch is not None:
                detected_indices[ch] = idx

        if not detected_indices:
            # fallback: after time column, columns are Channel 0,1,2...
            ch_no = 0
            for idx, _name in enumerate(header):
                if idx == time_idx:
                    continue
                detected_indices[ch_no] = idx
                ch_no += 1

        channel_order = [ch for ch in required_channels if ch in detected_indices]
        if not channel_order:
            raise ValueError('No digital channels found in exported Saleae CSV.')

        max_idx = max([time_idx] + [detected_indices[ch] for ch in channel_order])
        txt_path.parent.mkdir(parents=True, exist_ok=True)
        rows_in = 0
        rows_out = 0
        previous_state = None

        with open(txt_path, 'w', encoding='utf-8', newline='') as out:
            out.write('# Saleae Sampling Assistant compact raw digital data\n')
            out.write('# format: time_s<TAB>state_bits\n')
            out.write('# channels: ' + ','.join(str(ch) for ch in channel_order) + '\n')
            out.write('# note: consecutive duplicate states are removed\n')
            out.write('time_s\tstate\n')

            for row in reader:
                if len(row) <= max_idx:
                    continue
                t = parse_time_seconds(row[time_idx])
                if t is None:
                    continue
                vals = []
                for ch in channel_order:
                    val = parse_digital_value(row[detected_indices[ch]])
                    vals.append('1' if val == 1 else '0')
                state = ''.join(vals)
                rows_in += 1
                if state == previous_state:
                    continue
                previous_state = state
                out.write(f'{t:.9f}\t{state}\n')
                rows_out += 1

    return rows_out, rows_in


def load_compact_raw_txt(txt_path):
    txt_path = Path(txt_path)
    channel_order = None
    t_list = []
    channel_map = {}

    with open(txt_path, 'r', encoding='utf-8-sig', newline='') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('#'):
                if line.lower().startswith('# channels:'):
                    raw = line.split(':', 1)[1].strip()
                    channel_order = [int(x.strip()) for x in raw.split(',') if x.strip() != '']
                    channel_map = {ch: [] for ch in channel_order}
                continue
            if line.lower().startswith('time_s'):
                continue
            if channel_order is None:
                return None
            parts = line.split('\t')
            if len(parts) < 2:
                continue
            t = parse_time_seconds(parts[0])
            state = parts[1].strip()
            if t is None or len(state) < len(channel_order):
                continue
            t_list.append(t)
            for idx, ch in enumerate(channel_order):
                channel_map[ch].append(1 if state[idx] == '1' else 0)

    if not t_list or not channel_map:
        return None
    return {'time': t_list, 'channels': channel_map}

def load_saleae_csv(csv_path):
    try:
        csv_path = Path(csv_path)
        # The saved raw file is normally compact .txt. Keep the function name
        # for analyzer compatibility, but dispatch based on the file header.
        try:
            with open(csv_path, "r", encoding="utf-8-sig", newline="") as probe:
                first = probe.readline()
            if first.startswith('# Saleae Sampling Assistant compact raw digital data') or first.startswith('# Saleae Sampling Assist compact raw digital data'):
                return load_compact_raw_txt(csv_path)
        except Exception:
            pass

        with open(csv_path, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f)
            header = next(reader)

            time_idx = find_time_column(header)
            channel_map = {}
            channel_indices = {}

            for idx, name in enumerate(header):
                if idx == time_idx:
                    continue
                ch = parse_channel_number(name)
                if ch is not None:
                    channel_indices[idx] = ch
                    channel_map[ch] = []

            if not channel_map:
                # fallback: time 다음 컬럼부터 Channel 0,1,2...로 간주
                ch_no = 0
                for idx, name in enumerate(header):
                    if idx == time_idx:
                        continue
                    channel_indices[idx] = ch_no
                    channel_map[ch_no] = []
                    ch_no += 1

            t_list = []

            max_required_idx = max([time_idx] + list(channel_indices.keys()))

            for row in reader:
                if len(row) <= max_required_idx:
                    continue
                t = parse_time_seconds(row[time_idx])
                if t is None:
                    continue
                t_list.append(t)

                for idx, ch in channel_indices.items():
                    val = parse_digital_value(row[idx])
                    if val is None:
                        val = 0
                    channel_map[ch].append(val)

        if not t_list:
            return None

        return {
            "time": t_list,
            "channels": channel_map,
        }

    except Exception:
        return None


def analyze_reference_clock(t, v, expected_hz, tolerance_percent):
    events = []
    duration = max(t[-1] - t[0], 1e-12)

    edge_times_raw = edge_times(t, v)

    expected_half_period = 1.0 / (2.0 * expected_hz)
    glitch_limit = expected_half_period * REF_GLITCH_HALF_PERIOD_RATIO

    accepted_edges = []
    glitch_edges = 0
    last_edge = None

    for et in edge_times_raw:
        if last_edge is None:
            accepted_edges.append(et)
            last_edge = et
            continue

        gap = et - last_edge
        if gap < glitch_limit:
            glitch_edges += 1
            # glitch는 last_edge를 업데이트하지 않음
            continue

        accepted_edges.append(et)
        last_edge = et

    edge_count = len(accepted_edges)
    freq_hz = edge_count / (2.0 * duration) if duration > 0 else 0.0
    error_percent = abs(freq_hz - expected_hz) / expected_hz * 100.0
    glitch_ratio = glitch_edges / max(len(edge_times_raw), 1)

    metrics = {
        "duration_sec": duration,
        "raw_edge_count": len(edge_times_raw),
        "edge_count": edge_count,
        "glitch_edges": glitch_edges,
        "glitch_ratio": glitch_ratio,
        "freq_hz": freq_hz,
        "expected_hz": expected_hz,
        "error_percent": error_percent,
        "tolerance_percent": tolerance_percent,
    }

    if edge_count < 2:
        events.append({
            "channel": f"Channel {CH_REF}",
            "event_type": "REF_NO_CLOCK",
            "detail": f"accepted_edges={edge_count}",
        })
        return metrics, events

    if error_percent > tolerance_percent:
        events.append({
            "channel": f"Channel {CH_REF}",
            "event_type": "REF_FREQ_OUT_OF_TOLERANCE",
            "detail": f"measured={freq_hz:.6f}Hz, expected={expected_hz:.6f}Hz, error={error_percent:.3f}%, limit={tolerance_percent:.3f}%",
        })

    if glitch_ratio > REF_MAX_GLITCH_EDGE_RATIO:
        events.append({
            "channel": f"Channel {CH_REF}",
            "event_type": "REF_TOO_MANY_GLITCH_EDGES",
            "detail": f"glitch_ratio={glitch_ratio:.3f}, limit={REF_MAX_GLITCH_EDGE_RATIO:.3f}, glitch_edges={glitch_edges}, raw_edges={len(edge_times_raw)}",
        })

    return metrics, events


def reconstruct_diff_pair_receiver_view(t, p, n, pair_name):
    """
    단일 엔디드 digital 값을 이용해 차동 수신기 관점의 논리 신호를 복원합니다.

    p != n이면 수신기가 해석 가능한 상태로 보고 p 값을 receiver-view로 사용합니다.
    p == n이면 원칙적으로 차동 수신기 입장에서는 불명확합니다.
    다만 edge skew 때문에 짧게 발생하는 p == n 구간은 이전 유효 상태를 유지한 것으로 처리합니다.
    """
    rx = []
    events = []
    last_valid = None
    equal_runs = []

    i = 0
    length = len(t)

    while i < length:
        pv = p[i]
        nv = n[i]

        if pv != nv:
            last_valid = pv
            rx.append(last_valid)
            i += 1
            continue

        # equal run 시작
        start_idx = i
        j = i
        while j + 1 < length and p[j + 1] == n[j + 1]:
            j += 1

        start_time = t[start_idx]
        end_time = t[j + 1] if j + 1 < length else t[j]
        duration = max(end_time - start_time, 0.0)
        equal_runs.append(duration)

        if duration > DIFF_EQUAL_MAX_SEC:
            events.append({
                "channel": pair_name,
                "event_type": "DIFF_PAIR_UNDEFINED_TOO_LONG",
                "detail": f"equal_duration={duration:.9f}s, limit={DIFF_EQUAL_MAX_SEC:.9f}s, start={start_time:.9f}s",
            })

        # 짧은 equal 상태는 수신기 전환 구간으로 보고 이전 유효 상태 유지
        if last_valid is None:
            # 시작부터 equal이면 임시로 p 사용. 이후 긴 equal이면 위에서 NG.
            last_valid = pv

        for _ in range(start_idx, j + 1):
            rx.append(last_valid)

        i = j + 1

    total_equal = sum(equal_runs)
    max_equal = max(equal_runs) if equal_runs else 0.0

    metrics = {
        "equal_run_count": len(equal_runs),
        "total_equal_sec": total_equal,
        "max_equal_sec": max_equal,
        "diff_equal_limit_sec": DIFF_EQUAL_MAX_SEC,
    }

    return rx, metrics, events


def analyze_ssi_clock_rx(t, clk):
    e = edge_times(t, clk)
    duration = max(t[-1] - t[0], 1e-12)

    if len(e) < 2:
        return {
            "edge_count": len(e),
            "edge_rate": len(e) / duration,
            "active_half_period_median_sec": 0.0,
            "active_half_period_p95_sec": 0.0,
            "long_gap_median_sec": 0.0,
            "long_gap_count": 0,
        }

    gaps = [e[i] - e[i - 1] for i in range(1, len(e)) if e[i] >= e[i - 1]]
    if not gaps:
        return {
            "edge_count": len(e),
            "edge_rate": len(e) / duration,
            "active_half_period_median_sec": 0.0,
            "active_half_period_p95_sec": 0.0,
            "long_gap_median_sec": 0.0,
            "long_gap_count": 0,
        }

    # SSI clock은 active half-period와 frame gap이 섞임.
    # median 근처를 active half-period로 보고, median*10 이상을 frame gap으로 봅니다.
    med = median(gaps)
    active = [g for g in gaps if g <= med * 3.0]
    long_gaps = [g for g in gaps if g >= med * 10.0]

    return {
        "edge_count": len(e),
        "edge_rate": len(e) / duration,
        "active_half_period_median_sec": median(active) if active else 0.0,
        "active_half_period_p95_sec": percentile(active, 95) if active else 0.0,
        "active_half_period_p99_sec": percentile(active, 99) if active else 0.0,
        "long_gap_median_sec": median(long_gaps) if long_gaps else 0.0,
        "long_gap_count": len(long_gaps),
        "max_gap_sec": max(gaps),
    }


def analyze_ssi_data_rx(t, data):
    e = edge_times(t, data)
    duration = max(t[-1] - t[0], 1e-12)

    if len(e) < 2:
        max_stable = duration
    else:
        all_points = [t[0]] + e + [t[-1]]
        stable_gaps = [all_points[i] - all_points[i - 1] for i in range(1, len(all_points))]
        max_stable = max(stable_gaps) if stable_gaps else duration

    return {
        "edge_count": len(e),
        "edge_rate": len(e) / duration,
        "max_stable_sec": max_stable,
        "duration_sec": duration,
    }


def compare_to_baseline(current, baseline):
    events = []

    # SSI CLOCK active half-period 비교
    cur_half = current["clk"].get("active_half_period_median_sec", 0.0)
    base_half = baseline["clk"].get("active_half_period_median_sec", 0.0)

    if base_half > 0 and cur_half > 0:
        err = abs(cur_half - base_half) / base_half * 100.0
        if err > SSI_CLK_HALF_PERIOD_TOL_PERCENT:
            events.append({
                "channel": "SSI_CLOCK",
                "event_type": "CLK_HALF_PERIOD_MISMATCH",
                "detail": f"current={cur_half*1e6:.6f}us, reference={base_half*1e6:.6f}us, error={err:.3f}%, limit={SSI_CLK_HALF_PERIOD_TOL_PERCENT:.3f}%",
            })
    else:
        events.append({
            "channel": "SSI_CLOCK",
            "event_type": "CLK_HALF_PERIOD_INVALID",
            "detail": f"current={cur_half}, reference={base_half}",
        })

    # SSI CLOCK edge count 비교
    cur_edges = current["clk"].get("edge_count", 0)
    base_edges = baseline["clk"].get("edge_count", 0)
    if base_edges > 0:
        err = abs(cur_edges - base_edges) / base_edges * 100.0
        if err > SSI_CLK_EDGE_COUNT_TOL_PERCENT:
            events.append({
                "channel": "SSI_CLOCK",
                "event_type": "CLK_EDGE_COUNT_MISMATCH",
                "detail": f"current={cur_edges}, reference={base_edges}, error={err:.3f}%, limit={SSI_CLK_EDGE_COUNT_TOL_PERCENT:.3f}%",
            })

    # SSI CLOCK long gap 비교. clock burst 사이 gap이 갑자기 길어지는지 확인.
    cur_long = current["clk"].get("long_gap_median_sec", 0.0)
    base_long = baseline["clk"].get("long_gap_median_sec", 0.0)
    if base_long > 0 and cur_long > 0:
        err = abs(cur_long - base_long) / base_long * 100.0
        if err > SSI_CLK_LONG_GAP_TOL_PERCENT:
            events.append({
                "channel": "SSI_CLOCK",
                "event_type": "CLK_FRAME_GAP_MISMATCH",
                "detail": f"current={cur_long*1e6:.6f}us, reference={base_long*1e6:.6f}us, error={err:.3f}%, limit={SSI_CLK_LONG_GAP_TOL_PERCENT:.3f}%",
            })

    # DATA edge count 비교. 너무 줄면 stuck 가능성.
    cur_data_edges = current["data"].get("edge_count", 0)
    base_data_edges = baseline["data"].get("edge_count", 0)
    if base_data_edges > 0:
        ratio = cur_data_edges / base_data_edges
        if ratio < SSI_DATA_EDGE_COUNT_DROP_LIMIT:
            events.append({
                "channel": "SSI_DATA",
                "event_type": "DATA_EDGE_COUNT_TOO_LOW",
                "detail": f"current={cur_data_edges}, reference={base_data_edges}, ratio={ratio:.3f}, min_ratio={SSI_DATA_EDGE_COUNT_DROP_LIMIT:.3f}",
            })
        if ratio > SSI_DATA_EDGE_COUNT_RISE_LIMIT:
            events.append({
                "channel": "SSI_DATA",
                "event_type": "DATA_EDGE_COUNT_TOO_HIGH",
                "detail": f"current={cur_data_edges}, reference={base_data_edges}, ratio={ratio:.3f}, max_ratio={SSI_DATA_EDGE_COUNT_RISE_LIMIT:.3f}",
            })

    # DATA stuck check
    cur_stable = current["data"].get("max_stable_sec", 0.0)
    base_stable = baseline["data"].get("max_stable_sec", 0.0)
    limit = max(base_stable * SSI_DATA_STUCK_MULTIPLIER, SSI_DATA_STUCK_MIN_LIMIT_SEC)
    if cur_stable > limit:
        events.append({
            "channel": "SSI_DATA",
            "event_type": "DATA_STUCK_TOO_LONG",
            "detail": f"current_max_stable={cur_stable:.9f}s, reference={base_stable:.9f}s, limit={limit:.9f}s",
        })

    return events


def edge_times(t, v):
    result = []
    if not t or not v:
        return result
    prev = v[0]
    for i in range(1, min(len(t), len(v))):
        if v[i] != prev:
            result.append(t[i])
            prev = v[i]
    return result


def median(values):
    if not values:
        return 0.0
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2.0


def percentile(values, p):
    if not values:
        return 0.0
    s = sorted(values)
    if len(s) == 1:
        return s[0]
    k = (len(s) - 1) * (p / 100.0)
    f = int(k)
    c = min(f + 1, len(s) - 1)
    if f == c:
        return s[f]
    return s[f] * (c - k) + s[c] * (k - f)


def find_time_column(header):
    for idx, name in enumerate(header):
        lname = name.lower()
        if "time" in lname:
            return idx
    return 0


def parse_channel_number(name):
    s = str(name).strip().lower().replace("_", " ")
    if "channel" not in s:
        return None
    parts = s.split()
    for p in reversed(parts):
        try:
            return int(p)
        except Exception:
            continue
    return None


def parse_time_seconds(value):
    try:
        return float(str(value).strip())
    except Exception:
        return None


def parse_digital_value(value):
    s = str(value).strip().lower()

    if s in ("1", "true", "high", "h"):
        return 1

    if s in ("0", "false", "low", "l"):
        return 0

    try:
        v = float(s)
        return 1 if v >= 0.5 else 0
    except Exception:
        return None



def format_hhmmss(total_seconds):
    total_seconds = int(max(0, total_seconds))
    h = total_seconds // 3600
    m = (total_seconds % 3600) // 60
    s = total_seconds % 60
    return f"{h:02d}:{m:02d}:{s:02d}"


def format_mmss(total_seconds):
    total_seconds = int(max(0, total_seconds))
    m = total_seconds // 60
    s = total_seconds % 60
    return f"{m:02d}:{s:02d}"


